+const quizForm = document.querySelector("#language-quiz");
+const result = document.querySelector("#quiz-result");
+
+const questions = [
+  {
+    name: "programming-languages",
+    errorId: "question-1-error",
+  },
+  {
+    name: "web-languages",
+    errorId: "question-2-error",
+  },
+  {
+    name: "data-languages",
+    errorId: "question-3-error",
+  },
+];
+
+quizForm.addEventListener("submit", (event) => {
+  event.preventDefault();
+
+  let firstInvalidInput = null;
+  const answers = {};
+
+  questions.forEach(({ name, errorId }, index) => {
+    const selected = Array.from(quizForm.querySelectorAll(`input[name="${name}"]:checked`));
+    const errorMessage = document.querySelector(`#${errorId}`);
+    const inputs = Array.from(quizForm.querySelectorAll(`input[name="${name}"]`));
+
+    inputs.forEach((input) => {
+      input.removeAttribute("aria-invalid");
+    });
+
+    if (selected.length === 0) {
+      errorMessage.textContent = `Choose at least one answer for question ${index + 1}.`;
+      inputs.forEach((input) => {
+        input.setAttribute("aria-invalid", "true");
+      });
+
+      firstInvalidInput ??= inputs[0];
+      return;
+    }
+
+    errorMessage.textContent = "";
+    answers[name] = selected.map((input) => input.value);
+  });
+
+  if (firstInvalidInput) {
+    result.textContent = "Please answer every question before submitting.";
+    firstInvalidInput.focus();
+    return;
+  }
+
+  const answerSummary = Object.values(answers)
+    .map((selectedAnswers, index) => `Question ${index + 1}: ${selectedAnswers.join(", ")}`)
+    .join(" | ");
+
+  result.textContent = `Quiz submitted. ${answerSummary}`;
+});
+

')
